#include <bits/stdc++.h>
using namespace std;

int n;
vector<long long> tree;                  // 합이 int 를 넘을 수 있어요

void add(int i, long long delta) {       // i 는 1부터
    for (; i <= n; i += i & -i) tree[i] += delta;
}

long long prefix(int i) {                // a[1] + ... + a[i]
    long long s = 0;
    for (; i > 0; i -= i & -i) s += tree[i];
    return s;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int q;
    cin >> n >> q;
    vector<long long> a(n + 1);
    tree.assign(n + 1, 0);
    for (int i = 1; i <= n; i++) {
        cin >> a[i];
        add(i, a[i]);
    }
    while (q--) {
        int op;
        long long x, y;
        cin >> op >> x >> y;
        if (op == 1) {                   // a[x] 를 y 로 바꾸기
            add(x, y - a[x]);            // 펜윅에는 변화량을 더해요
            a[x] = y;
        } else {                         // a[x..y] 의 합
            cout << prefix(y) - prefix(x - 1) << '\n';
        }
    }
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

int n;
vector<int> tree;                        // 반복형: 잎은 tree[n..2n-1]

void update(int i, int value) {          // a[i] = value (0-based)
    i += n;
    tree[i] = value;
    for (i /= 2; i >= 1; i /= 2) tree[i] = min(tree[2 * i], tree[2 * i + 1]);
}

int query(int l, int r) {                // min(a[l..r-1]), 반열린 구간 [l, r)
    int res = INT_MAX;
    for (l += n, r += n; l < r; l /= 2, r /= 2) {
        if (l & 1) res = min(res, tree[l++]);
        if (r & 1) res = min(res, tree[--r]);
    }
    return res;
}

int main() {
    vector<int> a = {7, 2, 9, 4, 6, 1, 8};
    n = a.size();
    tree.assign(2 * n, INT_MAX);
    for (int i = 0; i < n; i++) tree[n + i] = a[i];
    for (int i = n - 1; i >= 1; i--) tree[i] = min(tree[2 * i], tree[2 * i + 1]);

    cout << query(0, 7) << ' ' << query(0, 3) << ' ' << query(2, 5) << '\n';
    update(5, 10);                       // a[5]: 1 -> 10
    cout << query(0, 7) << ' ' << query(4, 7) << '\n';
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

int k;
vector<int> tree;

void add(int i) {
    for (; i <= k; i += i & -i) tree[i]++;
}

int prefix(int i) {
    int s = 0;
    for (; i > 0; i -= i & -i) s += tree[i];
    return s;
}

int main() {
    vector<int> a = {30, 10, 50, 10, 20};
    // 좌표 압축: 값을 1..k 순위로 바꾸기
    vector<int> vals = a;
    sort(vals.begin(), vals.end());
    vals.erase(unique(vals.begin(), vals.end()), vals.end());
    k = vals.size();
    tree.assign(k + 1, 0);

    long long inv = 0;                   // 역순쌍은 최대 N(N-1)/2 개라 long long
    for (int i = 0; i < (int)a.size(); i++) {
        int r = lower_bound(vals.begin(), vals.end(), a[i]) - vals.begin() + 1;
        inv += i - prefix(r);            // 앞에 나온 수 중 a[i] 보다 큰 것의 개수
        add(r);
    }
    cout << inv << '\n';
    return 0;
}
